_warned = set()
def _warn(key:str, msg:str):
    "Print `msg` to stderr once per process. A warning is better than an empty result with no explanation."
    if key not in _warned:
        _warned.add(key)
        print(f'fossick: {msg}', file=sys.stderr)

def ddgs_env() -> dict:
    "Return proxy and certificate settings for ddgs, read from the environment."
    ev = lambda *ks: first(os.environ.get(k) for k in ks if os.environ.get(k))
    ca = ev('FOSSICK_CA_BUNDLE', 'SSL_CERT_FILE', 'REQUESTS_CA_BUNDLE', 'CURL_CA_BUNDLE')
    return dict(proxy=ev('DDGS_PROXY', 'HTTPS_PROXY', 'https_proxy'), verify=ca or True)

_ddgs = {}
def get_ddgs(timeout:int=10):
	"Return the shared ddgs client for these timeout, proxy and certificate settings."
	env = ddgs_env()
	if (key := (timeout, *sorted(env.items()))) not in _ddgs:
		try: from ddgs import DDGS
		except ImportError as e: raise ImportError('web search needs ddgs: pip install ddgs') from e
		_ddgs[key] = DDGS(timeout=timeout, **env)
	return _ddgs[key]

